```python
class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        raise NotImplementedError("Subclass must implement abstract method")

    def move(self):
        raise NotImplementedError("Subclass must implement abstract method")


class Mammal(Animal):
    def speak(self):
        return "Mammal speaking"

    def move(self):
        return "Mammal moving"


class Bird(Animal):
    def speak(self):
        return "Bird speaking"

    def move(self):
        return "Bird moving"


class FlyingMammal(Mammal, Bird):
    def speak(self):
        return super().speak() + " and flying"

    def move(self):
        return super().move() + " and flying"


