        lion.show(); // Output: This is an Animal.
        lion.eatMeat(); // Output: Lion eats meat.
        cow.show(); // Output: This is an Animal.
        cow.eatPlants(); // Output: Cow eats plants.
        lioness.show(); // Output: This is an Animal.
        lioness.eatMeat(); // Output: Lion eats meat.
        lioness.display(); // Output: This is a Lioness.
